import React, { type ReactNode } from 'react';
import {
  Box,
  Button,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  CheckCircle as ImportedIcon,
  ErrorOutline as FailedIcon,
  ReportProblem as InvalidIcon,
  Replay as DuplicateIcon,
  WarningAmber as BillRequiredIcon,
} from '@mui/icons-material';
import { calmImportLead, type LastAccountingImportResult } from './accountingImportResult';

interface AccountingImportSummaryProps {
  result: LastAccountingImportResult;
  onViewImported: () => void;
  onReviewBillRequired: () => void;
  onViewImportDetails: () => void;
  onViewAllImportedActivity?: () => void;
  onDownloadAuditWorkbook?: () => void;
  headerAction?: ReactNode;
}

const visuallyHiddenSx = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0 0 0 0)',
  whiteSpace: 'nowrap',
  border: 0,
};

const summaryCardSx = {
  minWidth: 0,
  height: '100%',
  p: 1.5,
  borderRadius: 2,
  border: '1px solid',
  borderColor: (theme: { palette: { mode: string } }) =>
    theme.palette.mode === 'dark' ? 'rgba(148, 163, 184, 0.22)' : 'rgba(148, 163, 184, 0.28)',
  bgcolor: (theme: { palette: { mode: string } }) =>
    theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.03)' : 'rgba(15, 23, 42, 0.03)',
};

const actionButtonSx = {
  height: 40,
  minHeight: 40,
  px: 1.5,
  py: 0,
  whiteSpace: 'nowrap',
  maxWidth: '100%',
};

const blueHoverSx = {
  transition: 'background-color 0.2s ease, border-color 0.2s ease',
  '&:hover': {
    borderColor: '#2196f3',
    backgroundColor: 'rgba(33, 150, 243, 0.12)',
  },
};

const statusCards = (result: LastAccountingImportResult) => ([
  {
    key: 'imported',
    label: 'Imported successfully',
    count: result.totals.imported,
    icon: <ImportedIcon fontSize="small" color="success" />,
    color: 'success.main',
  },
  {
    key: 'billRequired',
    label: 'Bill required',
    count: result.totals.pendingBillUpload,
    icon: <BillRequiredIcon fontSize="small" color="warning" />,
    color: 'warning.main',
  },
  {
    key: 'duplicates',
    label: 'Duplicates',
    count: result.totals.duplicates,
    icon: <DuplicateIcon fontSize="small" color="action" />,
    color: 'text.secondary',
  },
  {
    key: 'invalid',
    label: 'Invalid',
    count: result.totals.invalid,
    icon: <InvalidIcon fontSize="small" color="warning" />,
    color: 'warning.dark',
  },
  {
    key: 'failed',
    label: 'Failed',
    count: result.totals.persistFailures,
    icon: <FailedIcon fontSize="small" color="error" />,
    color: 'error.main',
  },
]);

const AccountingImportSummary: React.FC<AccountingImportSummaryProps> = ({
  result,
  onViewImported,
  onReviewBillRequired,
  onViewImportDetails,
  onViewAllImportedActivity,
  onDownloadAuditWorkbook,
  headerAction,
}) => {
  const cards = statusCards(result).filter((card) => card.key === 'imported' || card.count > 0);
  const formatHint = result.detection?.format || result.importMeta?.format;
  const importedDisabled = result.totals.imported <= 0;
  const billRequiredDisabled = result.totals.pendingBillUpload <= 0;
  const previewNote = /showing the first/i.test(result.message || '') ? result.message : null;
  const loadedPreviewCount = result.imported.length;
  const importedTotal = result.totals.imported;
  const previewCountLine = importedTotal > loadedPreviewCount
    ? `${loadedPreviewCount.toLocaleString('en-IN')} loaded preview ${loadedPreviewCount === 1 ? 'row' : 'rows'} · ${importedTotal.toLocaleString('en-IN')} imported in total. The preview is not the full import.`
    : `${loadedPreviewCount.toLocaleString('en-IN')} loaded preview ${loadedPreviewCount === 1 ? 'row' : 'rows'} · ${importedTotal.toLocaleString('en-IN')} imported in total.`;

  const carbonQueued = result.carbonAnalysisStatus === 'queued';
  const sourceMeta = [result.providerLabel, formatHint].filter(Boolean).join(' · ');

  return (
    <Paper
      variant="outlined"
      sx={{ p: { xs: 1.5, sm: 2 }, mb: 2, minWidth: 0 }}
      aria-live="polite"
      aria-atomic="true"
    >
      <Stack
        direction="row"
        spacing={1.5}
        flexWrap="wrap"
        useFlexGap
        alignItems="flex-start"
        justifyContent="space-between"
        sx={{ mb: 1.5, minWidth: 0 }}
      >
        <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ minWidth: 0, flex: '1 1 220px' }}>
          <Box
            sx={{
              width: 36,
              height: 36,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
              color: 'success.main',
              bgcolor: (theme) => (theme.palette.mode === 'dark'
                ? 'rgba(76, 175, 80, 0.16)'
                : 'rgba(76, 175, 80, 0.12)'),
            }}
          >
            <ImportedIcon fontSize="small" />
          </Box>
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="h6" component="h3" sx={{ fontWeight: 700, lineHeight: 1.3 }}>
              Import complete
            </Typography>
            <Typography
              variant="body1"
              sx={{ fontWeight: 600, mt: 0.25, wordBreak: 'break-word', overflowWrap: 'anywhere' }}
            >
              {result.fileName}
            </Typography>
            {sourceMeta && (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.25 }}>
                {sourceMeta}
              </Typography>
            )}
          </Box>
        </Stack>
        {headerAction ? <Box sx={{ flexShrink: 0 }}>{headerAction}</Box> : null}
      </Stack>

      <Box
        sx={{
          display: 'grid',
          gap: 1,
          mb: 1.5,
          minWidth: 0,
          gridTemplateColumns: { xs: 'minmax(0, 1fr)', sm: 'repeat(3, minmax(0, 1fr))' },
        }}
      >
        <Box sx={summaryCardSx}>
          <Typography variant="caption" color="text.secondary">Records received</Typography>
          <Typography variant="h5" component="p" sx={{ fontWeight: 700, lineHeight: 1.2, mt: 0.25 }}>
            {result.totals.received ?? '—'}
          </Typography>
          {result.totals.received != null && (
            <Box component="span" sx={visuallyHiddenSx}>{`Records received: ${result.totals.received}`}</Box>
          )}
        </Box>
        <Box sx={summaryCardSx}>
          <Typography variant="caption" color="text.secondary">Records parsed</Typography>
          <Typography variant="h5" component="p" sx={{ fontWeight: 700, lineHeight: 1.2, mt: 0.25 }}>
            {result.totals.parsed ?? '—'}
          </Typography>
          {result.totals.parsed != null && (
            <Box component="span" sx={visuallyHiddenSx}>{`Records parsed: ${result.totals.parsed}`}</Box>
          )}
        </Box>
        <Box sx={summaryCardSx}>
          <Typography variant="caption" color="text.secondary">Carbon calculation</Typography>
          <Typography
            variant={carbonQueued ? 'body1' : 'h5'}
            component="p"
            sx={{ fontWeight: 700, lineHeight: 1.3, mt: 0.5, wordBreak: 'break-word' }}
          >
            {carbonQueued ? 'Carbon figures will appear in a moment' : (result.carbonAnalysisStatus || '—')}
          </Typography>
        </Box>
      </Box>

      <Box
        sx={{
          mb: 1.5,
          px: 1.5,
          py: 1,
          borderRadius: 1.5,
          border: '1px solid',
          borderColor: (theme) => (theme.palette.mode === 'dark'
            ? 'rgba(76, 175, 80, 0.22)'
            : 'rgba(76, 175, 80, 0.18)'),
          bgcolor: (theme) => (theme.palette.mode === 'dark'
            ? 'rgba(76, 175, 80, 0.08)'
            : 'rgba(76, 175, 80, 0.06)'),
        }}
      >
        <Typography variant="body2">{calmImportLead(result)}</Typography>
        {previewNote && (
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
            {previewNote}
          </Typography>
        )}
      </Box>

      <Box
        sx={{
          display: 'grid',
          gap: 1,
          mb: 1.5,
          minWidth: 0,
          gridTemplateColumns: {
            xs: 'minmax(0, 1fr)',
            sm: 'repeat(2, minmax(0, 1fr))',
            md: 'repeat(auto-fit, minmax(140px, 1fr))',
          },
        }}
      >
        {cards.map((card) => (
          <Box key={card.key} sx={summaryCardSx}>
            <Stack direction="row" spacing={0.75} alignItems="center">
              {card.icon}
              <Typography variant="caption" color="text.secondary">
                {card.label}
              </Typography>
            </Stack>
            <Typography variant="h5" component="p" sx={{ fontWeight: 700, color: card.color, lineHeight: 1.2, mt: 0.5 }}>
              {card.count}
            </Typography>
            {card.key === 'imported' && (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
                {previewCountLine}
              </Typography>
            )}
          </Box>
        ))}
      </Box>

      <Stack
        direction="row"
        spacing={1}
        flexWrap="wrap"
        useFlexGap
        alignItems="center"
        sx={{ minWidth: 0, maxWidth: '100%' }}
      >
        <Button
          size="small"
          variant="contained"
          color="primary"
          disabled={importedDisabled}
          onClick={onViewImported}
          aria-label="View the loaded preview rows from this import"
          sx={actionButtonSx}
        >
          View imported preview
        </Button>
        {onDownloadAuditWorkbook && (
          <Button
            size="small"
            variant="outlined"
            color="primary"
            onClick={onDownloadAuditWorkbook}
            aria-label={`Download audit Excel for ${result.fileName}`}
            sx={actionButtonSx}
          >
            Download audit Excel
          </Button>
        )}
        <Button
          size="small"
          variant="outlined"
          color="inherit"
          disabled={billRequiredDisabled}
          onClick={onReviewBillRequired}
          aria-label="Review transactions that require a bill upload"
          sx={actionButtonSx}
        >
          Review bill required
        </Button>
        <Button
          size="small"
          variant="outlined"
          color="inherit"
          onClick={onViewImportDetails}
          aria-label="View the summary for this import"
          sx={{ ...actionButtonSx, ...blueHoverSx }}
        >
          View import summary
        </Button>
      </Stack>

      {onViewAllImportedActivity && (
        <Box sx={{ mt: 1.5 }}>
          <Button
            size="small"
            variant="text"
            onClick={onViewAllImportedActivity}
            aria-label="View all imported activity, not only this import"
            sx={{
              ...blueHoverSx,
              border: '1px solid transparent',
            }}
          >
            View all imported activity
          </Button>
          <Typography variant="caption" color="text.secondary" display="block">
            Opens all imported activity. It is not limited to this file.
          </Typography>
        </Box>
      )}
    </Paper>
  );
};

export default AccountingImportSummary;
