/**
 * Frontend-only mapping of the existing accounting file-import API response.
 * Counts and rows come from the response. No invented fields or hardcoded totals.
 */

export type ImportDetailsTab = 'imported' | 'billRequired' | 'duplicates' | 'invalid' | 'failed';

export const IMPORT_DETAILS_TABS: ImportDetailsTab[] = [
  'imported',
  'billRequired',
  'duplicates',
  'invalid',
  'failed',
];

export interface AccountingImportTotals {
  received?: number;
  parsed?: number;
  imported: number;
  duplicates: number;
  invalid: number;
  persistFailures: number;
  pendingBillUpload: number;
}

export interface ImportedAccountingRow {
  id?: string;
  rowIndex?: number;
  sourceId?: string | null;
  amount?: number;
  date?: string | Date;
}

export interface DuplicateAccountingRow {
  rowIndex?: number;
  sourceId?: string | null;
  reasons?: string[];
  similarityScore?: number;
}

export interface InvalidAccountingRow {
  rowIndex?: number;
  sourceId?: string | null;
  errors?: string[];
}

export interface PersistFailureAccountingRow {
  rowIndex?: number;
  sourceId?: string | null;
  error?: string;
}

export interface HighValueUploadRequest {
  workflow: string;
  userGuidance?: string;
  thresholdInr?: number;
  transactionPreview?: {
    sourceId?: string;
    amount?: number;
    description?: string;
    category?: string;
    date?: string;
  };
  requiredUpload?: {
    allowedMimeTypes?: string[];
    requiredPayload?: {
      documentType?: string;
      sourceWorkflow?: string;
      linkedSourceId?: string;
      linkedTransactionId?: string;
    };
  };
}

export type HighValueBillUiStatus =
  | 'awaiting_bill'
  | 'uploaded'
  | 'processing'
  | 'processed'
  | 'matched'
  | 'mismatch'
  | 'needs_verification'
  | 'verified'
  | 'failed';

export interface PendingBillUpload {
  rowIndex: number;
  transactionId?: string;
  source?: string;
  sourceId?: string;
  amount?: number;
  description?: string;
  category?: string;
  actionRequired: boolean;
  billStatus?: HighValueBillUiStatus;
  documentId?: string;
  statusMessage?: string;
  uploadRequest: HighValueUploadRequest;
}

export interface AccountingImportDetection {
  accepted?: boolean;
  provider?: string;
  format?: string;
  keywordScore?: number;
  headerMatches?: number;
  matchedKeywords?: string[];
}

export interface AccountingImportMeta {
  format?: string;
  voucherCount?: number;
  transactionCount?: number;
  headers?: string[];
  parser?: string;
  textLength?: number;
}

export interface LastAccountingImportResult {
  providerId: string;
  providerLabel: string;
  fileName: string;
  message?: string;
  actionRequired: boolean;
  carbonAnalysisStatus?: string;
  totals: AccountingImportTotals;
  imported: ImportedAccountingRow[];
  pendingBillUpload: PendingBillUpload[];
  duplicates: DuplicateAccountingRow[];
  invalidRows: InvalidAccountingRow[];
  persistFailures: PersistFailureAccountingRow[];
  detection?: AccountingImportDetection | null;
  importMeta?: AccountingImportMeta | null;
  connectorTransactions?: {
    count?: number;
    importedIds?: string[];
  };
}

const toFiniteCount = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const toOptionalFiniteCount = (value: unknown): number | undefined => {
  if (value == null || value === '') {
    return undefined;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
};

const asRecord = (value: unknown): Record<string, unknown> | null => (
  value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null
);

const asArray = <T>(value: unknown): T[] => (Array.isArray(value) ? value as T[] : []);

export const mapPendingBillUploads = (value: unknown): PendingBillUpload[] => (
  asArray<PendingBillUpload>(value)
);

export const mapAccountingImportResult = ({
  data,
  providerId,
  providerLabel,
  fileName,
  message,
}: {
  data: unknown;
  providerId: string;
  providerLabel: string;
  fileName: string;
  message?: string;
}): LastAccountingImportResult => {
  const payload = asRecord(data) || {};
  const totalsRaw = asRecord(payload.totals) || {};

  const imported = asArray<ImportedAccountingRow>(payload.imported);
  const pendingBillUpload = mapPendingBillUploads(payload.pendingBillUpload);
  const duplicates = asArray<DuplicateAccountingRow>(payload.duplicates);
  const invalidRows = asArray<InvalidAccountingRow>(payload.invalidRows);
  const persistFailures = asArray<PersistFailureAccountingRow>(payload.persistFailures);

  const importedCount = totalsRaw.imported != null
    ? toFiniteCount(totalsRaw.imported)
    : imported.length;
  const pendingCount = totalsRaw.pendingBillUpload != null
    ? toFiniteCount(totalsRaw.pendingBillUpload)
    : pendingBillUpload.length;
  const duplicateCount = totalsRaw.duplicates != null
    ? toFiniteCount(totalsRaw.duplicates)
    : duplicates.length;
  const invalidCount = totalsRaw.invalid != null
    ? toFiniteCount(totalsRaw.invalid)
    : invalidRows.length;
  const failedCount = totalsRaw.persistFailures != null
    ? toFiniteCount(totalsRaw.persistFailures)
    : persistFailures.length;

  return {
    providerId,
    providerLabel,
    fileName,
    message: typeof message === 'string' ? message : (typeof payload.message === 'string' ? payload.message : undefined),
    actionRequired: Boolean(payload.actionRequired),
    carbonAnalysisStatus: typeof payload.carbonAnalysisStatus === 'string'
      ? payload.carbonAnalysisStatus
      : undefined,
    totals: {
      received: toOptionalFiniteCount(totalsRaw.received),
      parsed: toOptionalFiniteCount(totalsRaw.parsed),
      imported: importedCount,
      duplicates: duplicateCount,
      invalid: invalidCount,
      persistFailures: failedCount,
      pendingBillUpload: pendingCount,
    },
    imported,
    pendingBillUpload,
    duplicates,
    invalidRows,
    persistFailures,
    detection: asRecord(payload.detection) as AccountingImportDetection | null,
    importMeta: asRecord(payload.importMeta) as AccountingImportMeta | null,
    connectorTransactions: asRecord(payload.connectorTransactions) as LastAccountingImportResult['connectorTransactions'],
  };
};

export const getImportCategoryCount = (
  result: LastAccountingImportResult,
  tab: ImportDetailsTab
): number => {
  switch (tab) {
    case 'imported':
      return result.totals.imported;
    case 'billRequired':
      return result.totals.pendingBillUpload;
    case 'duplicates':
      return result.totals.duplicates;
    case 'invalid':
      return result.totals.invalid;
    case 'failed':
      return result.totals.persistFailures;
    default:
      return 0;
  }
};

export const resolveImportDetailsTab = (tab: ImportDetailsTab | undefined): ImportDetailsTab => (
  tab && IMPORT_DETAILS_TABS.includes(tab) ? tab : 'imported'
);

export const formatImportAmount = (amount: unknown): string => {
  const value = Number(amount);
  if (!Number.isFinite(value)) {
    return '—';
  }
  return `₹${value.toLocaleString('en-IN')}`;
};

export const formatImportDate = (date: unknown): string => {
  if (date == null || date === '') {
    return '—';
  }
  const parsed = new Date(String(date));
  if (Number.isNaN(parsed.getTime())) {
    return String(date);
  }
  return parsed.toLocaleDateString();
};

export const pendingRowKey = (pending: Pick<PendingBillUpload, 'transactionId' | 'source' | 'sourceId' | 'rowIndex'>): string => {
  if (pending.transactionId) {
    return `txn:${pending.transactionId}`;
  }
  if (pending.source && pending.sourceId) {
    return `src:${pending.source}:${pending.sourceId}`;
  }
  if (pending.sourceId) {
    return `sid:${pending.sourceId}`;
  }
  return `row:${pending.rowIndex}`;
};

export const isSamePendingRow = (
  left: Pick<PendingBillUpload, 'transactionId' | 'source' | 'sourceId' | 'rowIndex'>,
  right: Pick<PendingBillUpload, 'transactionId' | 'source' | 'sourceId' | 'rowIndex'>
): boolean => pendingRowKey(left) === pendingRowKey(right);

export const mergePendingBillUploads = (
  left: PendingBillUpload[],
  right: PendingBillUpload[]
): PendingBillUpload[] => {
  const byKey = new Map<string, PendingBillUpload>();
  left.forEach((row) => {
    byKey.set(pendingRowKey(row), row);
  });
  right.forEach((row) => {
    const key = pendingRowKey(row);
    byKey.set(key, { ...byKey.get(key), ...row });
  });
  return Array.from(byKey.values());
};

export const reconcileImportPendingWithLive = (
  sessionRows: PendingBillUpload[],
  liveRows: PendingBillUpload[]
): { stillPending: PendingBillUpload[]; activatedCount: number } => {
  const stillPending = sessionRows
    .map((row) => liveRows.find((live) => isSamePendingRow(live, row)) || null)
    .filter((row): row is PendingBillUpload => row != null);
  return {
    stillPending,
    activatedCount: Math.max(0, sessionRows.length - stillPending.length),
  };
};

export const friendlyImportIssue = (message?: string | null): string => {
  const text = String(message || '').trim();
  if (!text) {
    return 'This row could not be read.';
  }
  if (/missing sourceid/i.test(text)) {
    return 'This row has no voucher number.';
  }
  if (/missing description/i.test(text)) {
    return 'This row has no description.';
  }
  if (/invalid or missing date/i.test(text)) {
    return 'This row needs a date.';
  }
  if (/invalid or missing amount|missing amount/i.test(text)) {
    return 'This row needs an amount greater than zero.';
  }
  if (/unrecognized unit/i.test(text)) {
    return 'Use a unit such as kWh, L, kg, tonne, or km.';
  }
  if (/missing unit/i.test(text)) {
    return 'Add a unit such as kWh, L, or kg on this row.';
  }
  if (/missing quantity/i.test(text)) {
    return 'Add the quantity on this row.';
  }
  if (/e11000|duplicate key/i.test(text)) {
    return 'This row is already saved.';
  }
  if (/^failed to persist/i.test(text)) {
    return 'This row could not be saved. Try the import again.';
  }
  if (/same sourceid/i.test(text)) {
    return 'Same voucher number as a row already saved.';
  }
  return text.length > 180 ? `${text.slice(0, 177)}…` : text;
};

export const calmImportLead = (result: LastAccountingImportResult): string => {
  const imported = result.totals.imported;
  const pending = result.totals.pendingBillUpload;
  const duplicates = result.totals.duplicates;
  const invalid = result.totals.invalid;
  const failed = result.totals.persistFailures;
  const parts: string[] = [];
  if (imported > 0) {
    parts.push(`${imported} ${imported === 1 ? 'row' : 'rows'} imported`);
  }
  if (pending > 0) {
    parts.push(`${pending} from ${importFileKindLabel(result.fileName)} need a bill`);
  }
  if (duplicates > 0) {
    parts.push(`${duplicates} already in the activity list`);
  }
  if (invalid > 0) {
    parts.push(`${invalid} skipped because a date, description, or amount was missing`);
  }
  if (failed > 0) {
    parts.push(`${failed} could not be saved`);
  }
  if (parts.length === 0) {
    return 'Nothing new was added from this file.';
  }
  return `${parts.join('. ')}.`;
};

export const importFileKindLabel = (fileName?: string): string => {
  const ext = String(fileName || '').split('.').pop()?.toLowerCase();
  if (ext === 'xlsx' || ext === 'xls') return 'Excel';
  if (ext === 'csv') return 'CSV';
  if (ext === 'xml') return 'XML';
  if (ext === 'pdf') return 'PDF';
  if (ext === 'json') return 'JSON';
  return 'file';
};

export const resolveInitialImportDetailsTab = (result: LastAccountingImportResult): ImportDetailsTab => {
  if (result.totals.imported > 0) {
    return 'imported';
  }
  const order: ImportDetailsTab[] = ['billRequired', 'duplicates', 'invalid', 'failed'];
  for (const tab of order) {
    if (getImportCategoryCount(result, tab) > 0) {
      return tab;
    }
  }
  return 'imported';
};

export const mapHighValueBillStatus = (value?: string | null): HighValueBillUiStatus => {
  switch (String(value || '')) {
    case 'uploaded':
      return 'uploaded';
    case 'processing':
      return 'processing';
    case 'processed':
      return 'processed';
    case 'matched':
    case 'matched_needs_verification':
      return 'matched';
    case 'mismatch':
      return 'mismatch';
    case 'needs_review':
    case 'needs_verification':
      return 'needs_verification';
    case 'verified_active':
    case 'verified':
      return 'verified';
    case 'failed':
      return 'failed';
    default:
      return 'awaiting_bill';
  }
};

export const formatHighValueBillStatus = (status?: HighValueBillUiStatus): string => {
  switch (status) {
    case 'uploaded':
      return 'Bill uploaded — processing';
    case 'processing':
      return 'Processing';
    case 'processed':
      return 'Processed';
    case 'matched':
      return 'Matched — needs verification';
    case 'mismatch':
      return 'This bill does not match the selected transaction.';
    case 'needs_verification':
      return 'Needs verification';
    case 'verified':
      return 'Verified and active';
    case 'failed':
      return 'Processing failed';
    default:
      return 'Awaiting supporting bill';
  }
};

export const formatSimilarityScore = (score: unknown): string => {
  const value = Number(score);
  if (!Number.isFinite(value)) {
    return '—';
  }
  return String(value);
};
